const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {screen:'creation', room:'chamber1', fresh:true, presence:'capsule', cover:true, tip:true, members:2, selectedPeer:'phone', peerLinked:false, pending:false, deviceLink:false,deviceCopied:false,lockConfigured:true,numericMode:'setup',numericOriginal:false, credentialSet:false, credentialExported:false, credentialVerified:false, credentialEditing:false, selectedFile:null, fileReading:false, fileError:'', gallery:'images', galleryPopulated:false, reduced:false, large:false, restoreProgress:0, restoreFailed:false, restoreDone:false, forceRestoreFailure:false, failSave:false};
let demoPassword='chamber-demo-2026', selectionId=0, toastTimer, transientId=0, creationFrame=0, restoreTimer=0;
let creation = {scenario:'normal', started:false, running:false, elapsed:0, start:0, pauseAt:0, paused:false};
let dialogCallback=null, dialogReturnFocus=null,numericDigits='',numericFirst='',numericBusy=false,numericTimer=0,numericDemo='123456',numericSetupForDevice=false,numericError='',numericShaking=false,numericShake=null;
