function updateChrome(){const scheme=document.documentElement.dataset.colorScheme;const color=getComputedStyle(device).getPropertyValue(['device-lock','numeric-password'].includes(state.screen)?'--numeric-page':state.screen==='cover-practice'?'--paper-pure':'--paper');$('meta[name=theme-color]').content=color.trim()||'#f2f5f1';$('#toggle-theme').textContent=scheme==='dark'?'浅色模式':'深色模式';$('#toggle-theme').setAttribute('aria-label',`切换为${scheme==='dark'?'浅':'深'}色模式`);}
