function paintCreation(elapsed){const scene=$('.portal-scene',app);if(!scene)return;const started=creation.started,failed=creation.scenario==='failed'&&elapsed>=2100,hold=creation.scenario==='slow'&&elapsed>=2300,ready=started&&elapsed>=3600;let open=Math.min(1,Math.max(0,(elapsed-3600)/960));open=1-(1-open)**3;scene.style.setProperty('--open',motionReduced()?0:open);scene.classList.toggle('is-started',started);scene.classList.toggle('is-failed',failed);scene.classList.toggle('is-ready',ready);scene.classList.toggle('is-paused',creation.paused);scene.setAttribute('aria-label',started?'正在创建密室':'创建密室');$('.creation-intro',scene).inert=started;$('.creation-intro',scene).setAttribute('aria-hidden',String(started));$('.creation-status',scene).inert=!started;$('.creation-status',scene).setAttribute('aria-hidden',String(!started));$('[data-portal-title]',scene).textContent=failed?'密室暂时未能创建':ready?'密室已准备好':elapsed>=2400?'正在确认密室':elapsed>=1200?'正在建立加密保护':'正在准备你的密室';$('[data-portal-note]',scene).textContent=failed?'网络暂时无法连接，准备未完成。':hold?'正在等待连接，密室准备好后继续':ready?'进入只属于你们的对话':'请稍等片刻';$('.creation-loading',scene).setAttribute('aria-label',ready?'密室已准备好':'正在创建');$('.portal-actions',scene).hidden=!failed;const slider=$('#door-seek');if(slider)slider.value=elapsed;const label=$('#seek-label');if(label)label.textContent=`${(elapsed/1000).toFixed(1)}s / 4.9s`;}
function showCreationStart(){cancelAnimationFrame(creationFrame);creation={scenario:'normal',started:false,running:false,elapsed:0,start:0,paused:false,pauseAt:0};render('creation','forward',{instant:true});}
function playCreation(scenario=creation.scenario,from=0){cancelAnimationFrame(creationFrame);creation={scenario,started:true,running:true,elapsed:from,start:performance.now()-from,paused:false,pauseAt:0};state.fresh=true;if(state.screen!=='creation'||!$('.portal-scene',app))render('creation','forward',{instant:true});else{paintCreation(from);drawInspector();}const frame=now=>{if(state.screen!=='creation'||!creation.running)return;const t=now-creation.start;creation.elapsed=creation.scenario==='slow'?Math.min(t,2300):creation.scenario==='failed'?Math.min(t,2100):t;paintCreation(creation.elapsed);if(creation.scenario==='failed'&&t>=2100){creation.running=false;return;}if(t>=4900&&creation.scenario==='normal'){creation.running=false;const scene=$('.surface:not(.retiring)',app);render('chat','forward',{instant:true});device.dataset.chromeClosing='creation';if(scene){scene.classList.add('creation-departing','retiring');scene.style.zIndex='55';scene.inert=true;app.append(scene);scene.animate([{opacity:1},{opacity:0}],{duration:motionReduced()?180:380,fill:'forwards'}).finished.then(()=>{scene.remove();if(device.dataset.chromeClosing==='creation')delete device.dataset.chromeClosing;});}return;}creationFrame=requestAnimationFrame(frame);};creationFrame=requestAnimationFrame(frame);}

