function beginRestore(){clearInterval(restoreTimer);state.restoreProgress=0;state.restoreFailed=false;state.restoreDone=false;render('restore-progress');const started=performance.now();restoreTimer=setInterval(()=>{if(state.screen!=='restore-progress'){clearInterval(restoreTimer);return;}const t=performance.now()-started;if(state.forceRestoreFailure&&t>2600){state.restoreFailed=true;state.forceRestoreFailure=false;clearInterval(restoreTimer);render('restore-progress','forward',{instant:true});return;}state.restoreProgress=Math.min(.98,t/5800);const p=state.restoreProgress;$('.progress-track>span',app)?.style.setProperty('--progress',p);$('.progress-track',app)?.setAttribute('aria-valuenow',String(Math.floor(p*100)));const note=$('[data-restore-stage]',app);if(note)note.textContent=p<.16?'正在读取并验证备份目录…':p>.9?'正在整理并保存记录…':`正在校验记录与原文件 · ${Math.floor(p*100)}%`;for(const [id,,total]of counts){const el=$(`[data-count=${id}]`,app);if(el)el.textContent=p<.16?'0 / 统计中':`${Math.min(total,Math.floor(total*(p-.16)/.78))} / ${total}`;}if(t>=5800){clearInterval(restoreTimer);state.restoreProgress=1;state.restoreDone=true;render('restore-progress','forward',{instant:true});}},120);}

function paintNumeric(){const root=$('.surface:not(.retiring) .numeric-page',app);if(!root)return;const setup=state.screen==='numeric-password'&&state.numericMode==='setup';$$('.numeric-dots i',root).forEach((dot,i)=>dot.classList.toggle('filled',numericShaking||i<numericDigits.length));$('[data-numeric-status]',root).textContent=`已输入 ${numericShaking?6:numericDigits.length} 位，共 6 位`;$$('.numeric-key',root).forEach(key=>key.disabled=numericBusy||numericShaking);const title=$('#numeric-title',root),description=$('#numeric-description',root);title.textContent=setup?(numericFirst?'确认应用锁':'设置应用锁'):'输入密码';description.textContent=numericError||(numericBusy?'正在验证…':setup?(numericFirst?'再次输入你的 6 位数字':'设置 6 位数字，用于本机日常解锁'):state.screen==='device-lock'?'验证后生成设备加入链接':'验证当前应用锁');description.classList.toggle('is-error',!!numericError);description.setAttribute('role',numericError?'alert':'status');}
