  if(action==='dismiss-tip'){state.tip=false;target.remove();return;}
  if(action==='copy-invite'){target.textContent='链接已复制';setTimeout(()=>{if(target.isConnected)target.textContent='复制密室加入链接';},1500);return;}
  if(action==='remove-device'){showConfirm('移除此设备？','iPad 将无法继续进入这间密室或收发消息。设备上已有的内容无法远程抹除。','移除设备',()=>{state.members=Math.max(1,state.members-1);render('devices','backward');toast('演示设备已移除');},true);return;}
  if(action==='copy-peer'){target.textContent='链接已复制';setTimeout(()=>{if(target.isConnected)target.textContent='复制密室进入链接';},1500);return;}
  if(action==='copy-device'){if(state.deviceLink){state.deviceCopied=true;render('add-device','forward',{instant:true});return;}if(state.members>=3){toast('设备已达上限，请先移除旧设备',true);return;}if(!state.lockConfigured){render('device-lock-needed');return;}numericDigits='';numericFirst='';numericBusy=false;render('device-lock');return;}
