  if(action==='numeric-cancel'){const returnTo=state.screen==='device-lock'||numericSetupForDevice?'add-device':'lock';clearTimeout(numericTimer);numericDigits='';numericFirst='';numericBusy=false;numericSetupForDevice=false;render(returnTo,'backward');return;}
  if(action==='setup-device-lock'){numericSetupForDevice=true;state.numericMode='setup';render('numeric-password');return;}
    if(action==='peer-continue'){showConfirm('替换这台设备？',`${state.selectedPeer==='phone'?'iPhone · Safari':'Mac · Chrome'} 将在新设备成功进入后被移出密室，无法继续收发。其他设备不受影响。`,'生成进入链接',()=>{state.peerLinked=false;render('peer-link');});return;}
  if(action==='peer-return-chat'){state.fresh=false;render('chat','backward');return;}
